 const source="export const cloudConfigured=()=>true;export async function connectCloud(){throw Error('offline');} export async function login(){} export async function logout(){} export async function loadCloud(){return [];} export async function saveCloud(){} export async function deleteCloud(){} export async function idToken(){return '';}";
 const a=await app(store,true,source,{initialHash:'#settings'});await new Promise(resolve=>setTimeout(resolve,0));
 assert.equal(a.vm.location.hash,'#settings');assert.equal(a.vm.startupEvents[0].part,'records');assert.equal(a.get('authChecking').hidden,true);
