test('manual loading and saving show progress and clear on completion or failure',async()=>{const source=syncMock.replace('return globalThis.remote||[];',"if(globalThis.blockRead)await new Promise(resolve=>globalThis.releaseRead=resolve);return globalThis.remote||[];").replace("if(globalThis.writeError)throw Error('offline');", "if(globalThis.blockWrite)await new Promise(resolve=>globalThis.releaseWrite=resolve);if(globalThis.writeError)throw Error('offline');");const a=await app(new Map(),true,source);a.vm.uploads=[];a.vm.blockRead=true;await a.changeAuth({uid:'same'});assert.equal(a.get('cloudProgress').hidden,true);const read=a.get('cloudSync').onclick();await new Promise(r=>setTimeout(r,0));assert.equal(a.get('cloudProgress').hidden,false);assert.match(a.get('cloudProgress').textContent,/불러오는/);assert.equal(a.get('cloudSync').disabled,true);assert.equal(a.get('cloudSync').attributes['aria-busy'],'true');a.vm.releaseRead();await read;assert.equal(a.get('cloudProgress').hidden,true);assert.equal(a.get('cloudSync').disabled,false);a.vm.blockRead=false;a.vm.blockWrite=true;a.vm.writeError=true;await save(a);assert.equal(a.get('cloudProgress').hidden,true);const write=a.get('cloudSync').onclick();for(let i=0;i<5&&typeof a.vm.releaseWrite!=='function';i++)await new Promise(r=>setTimeout(r,0));assert.equal(a.get('cloudProgress').hidden,false);assert.match(a.get('cloudProgress').textContent,/동기화/);a.vm.releaseWrite();await write;assert.equal(a.get('cloudProgress').hidden,true);assert.equal(a.get('cloudSync').attributes['aria-busy'],'false');assert.equal(a.get('cloudSync').disabled,false);});

