test('scoreless player additions and reordered results survive saving and reload until explicit reset',async()=>{const a=await app();await beginScoreless(a,'볼링','3','rank');const players=a.players();players.push({id:'result-new',name:'추가한 이름',color:'#45d9a0',score:null,rank:4,winner:false});const moved=players.pop();players.unshift(moved);players.forEach((player,index)=>{player.rank=index+1;player.winner=index===0;});a.vm.window.dispatchEvent(new a.vm.Event('scorecounter:changed'));const draftKey='score.scorelessDraft.v1.score.plays.v1.guest',draft=JSON.parse(a.store.get(draftKey));assert.equal(draft.step,'board');assert.equal(draft.count,4);assert.deepEqual(draft.players.map(player=>player.name),players.map(player=>player.name));const b=await app(a.store);assert.equal(b.get('scorelessBoardPanel').hidden,false);assert.equal(b.get('scorelessBoardTitle').textContent,'순위 기록');assert.deepEqual(b.players().map(player=>player.name),players.map(player=>player.name));assert.deepEqual(b.players().map(player=>player.rank),[1,2,3,4]);await finishScoreless(b,'볼링');assert.equal(b.bridge.context().records.length,1);assert.equal(JSON.parse(b.store.get(draftKey)).config.game.name,'볼링');const c=await app(b.store);assert.equal(c.get('scorelessBoardPanel').hidden,false);assert.equal(c.vm.window.ScoreCounter.getResultEntry().mode,'rank');assert.deepEqual(c.players().map(player=>player.rank),[1,2,3,4]);assert.equal(c.bridge.context().records.length,1);c.get('resetPlayers').onclick();assert.equal(c.store.get(draftKey),'null');assert.equal(c.players().length,0);assert.equal(c.bridge.context().records.length,1);});

async function startSession(a){a.bridge.openSave();a.get('playGame').value='카탄';a.get('playDate').value='2026-10-15';a.get('playRule').value='highest';await a.get('savePlayForm').onsubmit({preventDefault(){}});a.get('gamePlayerCount').value='2';a.get('gamePlayersForm').onsubmit({preventDefault(){}});}
test('score board SAVE opens the two-step game record form and keeps current scores after saving',async()=>{const a=await app();await startSession(a);const before=JSON.stringify(a.players());a.get('savePlay').onclick();assert.equal(a.get('endGameDialog').open,false);assert.equal(a.get('savePlayDialog').open,true);assert.equal(a.get('recordFormTitle').textContent,'경기 기록 저장');assert.equal(a.get('recordGameStep').hidden,false);await a.get('savePlayForm').onsubmit({preventDefault(){}});assert.equal(a.get('recordDetailsStep').hidden,false);await a.get('savePlayForm').onsubmit({preventDefault(){}});assert.equal(a.get('savePlayDialog').open,false);assert.equal(a.get('recordSavedNotice').hidden,false);assert.equal(a.get('recordSavedNotice').textContent,'점수가 기록되었습니다.');assert.equal(a.bridge.context().records.length,1);assert.equal(JSON.stringify(a.players()),before);});
test('a failed score save leaves the game record form and current points intact',async()=>{const a=await app();await startSession(a);const before=JSON.stringify(a.players());a.get('savePlay').onclick();await a.get('savePlayForm').onsubmit({preventDefault(){}});a.vm.localStorage.setItem=()=>{throw Error('quota');};await a.get('savePlayForm').onsubmit({preventDefault(){}});assert.equal(a.get('savePlayDialog').open,true);assert.equal(a.bridge.context().records.length,0);assert.equal(JSON.stringify(a.players()),before);assert.match(a.get('playError').textContent,/저장 공간/);});

test('scoreless entry reuses current players and skips participant selection without replacing a running game',async()=>{const a=await app();await startSession(a);a.get('savePlay').onclick();await a.get('endGameSave').onclick();await a.get('savePlayForm').onsubmit({preventDefault(){}});await a.get('savePlayForm').onsubmit({preventDefault(){}});const id=a.bridge.context().records[0].id,before=JSON.stringify(a.players()),session=a.store.get('score.activeGame.v1');a.bridge.openSave({withoutScores:true});assert.equal(a.get('scorelessSetupDialog').open,true);assert.equal(a.get('scorelessCountStep').hidden,true);assert.equal(a.get('scorelessModeStep').hidden,false);assert.equal(a.get('scorelessModeBack').hidden,true);a.get('scorelessRankMode').onclick();assert.equal(a.get('scorelessSetupDialog').open,false);assert.equal(a.get('scorelessBoardMode').textContent,'순위 기록 · 2/2');assert.deepEqual(a.players().map(p=>p.name),JSON.parse(before).map(p=>p.name));assert.deepEqual(a.players().map(p=>p.rank),[1,2]);a.players()[0].rank=2;a.players()[0].winner=false;a.players()[1].rank=1;a.players()[1].winner=true;await finishScoreless(a,'점수 없는 모임');assert.equal(a.bridge.context().records.length,2);const added=a.bridge.context().records.find(p=>p.id!==id);assert.equal(added.players.length,2);assert.ok(added.players.every(p=>p.score===null));assert.equal(added.players.map(p=>p.rank).join(','),'2,1');assert.equal(added.players.map(p=>p.winner).join(','),'false,true');assert.equal(a.vm.window.ScoreCounter.getResultEntry().mode,'rank');assert.deepEqual(a.players().map(p=>p.rank),[2,1]);assert.equal(a.store.get('score.activeGame.v1'),session);assert.equal(a.get('gamePlayersDialog').open,false);assert.equal(a.get('scorelessBoardPanel').hidden,false);a.get('scorelessResultBack').onclick();a.get('scoreModeOption').onclick();assert.equal(JSON.stringify(a.players()),before);});
test('scoreless entry validates participant count and requires complete results before opening record details',async()=>{const a=await app();a.vm.window.ScoreCounter.restorePlayers([]);a.bridge.openSave({withoutScores:true});for(const count of ['0','101','1.5']){a.get('scorelessCount').value=count;a.get('scorelessSetupForm').onsubmit({preventDefault(){}});assert.equal(a.bridge.context().records.length,0);assert.equal(a.get('scorelessCountStep').hidden,false);}a.get('scorelessCount').value='2';a.get('scorelessSetupForm').onsubmit({preventDefault(){}});assert.equal(a.get('scorelessModeStep').hidden,false);a.get('scorelessRankMode').onclick();delete a.players()[1].rank;delete a.players()[1].winner;a.get('savePlay').onclick();assert.equal(a.get('savePlayDialog').open,false);assert.equal(a.bridge.context().records.length,0);assert.match(a.get('scorelessBoardError').textContent,/모든 플레이어/);a.players()[1].rank=2;a.players()[1].winner=false;await finishScoreless(a,'Pandemic');assert.equal(a.bridge.context().records[0].players[0].score,null);assert.equal(a.bridge.context().records[0].rule,'highest');});
test('scoreless win mode saves draws and rank mode accepts competition-style shared ranks',async()=>{const draw=await app();await beginScoreless(draw,'축구','2','win');draw.players()[0].draw=true;draw.players()[1].draw=true;await finishScoreless(draw);assert.ok(draw.bridge.context().records[0].players.every(p=>p.draw===true&&p.score===null));draw.bridge.renderHistory();assert.ok(draw.get('recordList').children[0].children[2].children.every(row=>row.children[1].textContent==='무승부'));const rank=await app();await beginScoreless(rank,'볼링','3','rank');rank.players()[0].rank=1;rank.players()[0].winner=true;rank.players()[1].rank=1;rank.players()[1].winner=true;rank.players()[2].rank=3;rank.players()[2].winner=false;await finishScoreless(rank);assert.deepEqual(rank.bridge.context().records[0].players.map(p=>p.rank),[1,1,3]);});
