 const row=b.get('recordList').children[0].children[2].children[0];assert.equal(row.children[0].textContent,'성공');assert.equal(row.children[1].textContent,'미션 1 → 2 · 클리어 2 · 시도 3');
 const c=await app(b.store);c.vm.window.ScoreCounter.endResultEntry?.();c.vm.window.ScoreCounter.restorePlayers([]);c.bridge.openSave({withoutScores:true});c.get('scorelessCount').value='2';c.get('scorelessSetupForm').onsubmit({preventDefault(){}});c.get('scorelessMissionMode').onclick();
 const resume=c.get('scorelessMissionResume');assert.equal(resume.hidden,false);assert.equal(resume.children[0].textContent,'딥씨 크루 · 미션 3부터');resume.children[0].onclick();
 assert.equal(c.vm.window.ScoreCounter.getResultEntry().missionCurrent,3);assert.match(c.get('scorelessBoardTitle').textContent,/딥씨 크루/);
 const cRoster=c.players();c.vm.window.ScoreCounter.endResultEntry();c.vm.window.ScoreCounter.restoreResultEntry(cRoster,'coop',{cooperativeResult:'failure',missionAttempts:[{mission:3,result:'failure'}],missionCurrent:3});c.vm.window.dispatchEvent(new Event('scorecounter:changed'));assert.equal(resume.hidden,true);
