test('cooperative difficulty and campaign kinds restore after reload and save their new optional fields',async()=>{
 for(const [game,kind,details,field,value,label] of [['판데믹','difficulty',{difficulty:'영웅'},'difficulty','영웅','협력 난이도 기록'],['글룸헤이븐','campaign',{scenario:3},'scenario',3,'협력 캠페인 기록']]){
  const a=await app();await beginScoreless(a,game,'2','coop');a.get('scorelessCoopMode').onclick();a.get(kind==='difficulty'?'scorelessCoopDifficultyMode':'scorelessCoopCampaignMode').onclick();
  const api=a.vm.window.ScoreCounter;assert.equal(api.getResultEntry().coopKind,kind);assert.match(a.get('scorelessBoardMode').textContent,new RegExp(label));
  a.get('savePlay').onclick();assert.equal(a.get('savePlayDialog').open,false);
  const roster=a.players();api.endResultEntry();api.restoreResultEntry(roster,'coop',{coopKind:kind,cooperativeResult:'success',...details});a.vm.window.dispatchEvent(new Event('scorecounter:changed'));
  const b=await app(a.store);const restored=b.vm.window.ScoreCounter.getResultEntry();assert.equal(restored.coopKind,kind);assert.equal(restored[field],value);
  await finishScoreless(b,game);const saved=b.bridge.context().records[0];
  assert.equal(saved.rule,'cooperative');assert.equal(saved.cooperativeResult,'success');assert.equal(saved[field],value);assert.equal('sharedScore' in saved,false);assert.equal('missionAttempts' in saved,false);
 }
});
test('the hidden games tab ignores data events and renders once when shown',async()=>{const a=await app(new Map(),false,'',{entry:'games-screen.js',initialHash:'#home'}),list=a.get('gamesList');let renders=0;const replace=list.replaceChildren.bind(list);list.replaceChildren=(...items)=>{renders++;return replace(...items);};for(let i=0;i<5;i++){a.vm.window.dispatchEvent(new Event('score-bgg:changed'));a.vm.window.dispatchEvent(new Event('score-records:changed'));}assert.equal(renders,0);a.vm.location.hash='#games';a.vm.window.dispatchEvent(new Event('hashchange'));assert.equal(renders,1);a.vm.location.hash='#home';a.vm.window.dispatchEvent(new Event('hashchange'));a.vm.location.hash='#games';a.vm.window.dispatchEvent(new Event('hashchange'));assert.equal(renders,1,'unchanged data is not redrawn');a.vm.window.dispatchEvent(new Event('score-bgg:changed'));assert.equal(renders,2,'visible tab follows data changes');});
test('cloud upload sends pending records in parallel chunks and saves the device copy once per chunk',async()=>{const source=`export const cloudConfigured=()=>true;export async function connectCloud(cb){globalThis.changeAuth=cb;}export async function login(){}export async function logout(){}export async function loadCloud(){return [];}export async function saveCloud(play){globalThis.active++;globalThis.peak=Math.max(globalThis.peak,globalThis.active);await new Promise(resolve=>setTimeout(resolve,2));globalThis.active--;globalThis.saved.push(play.id);}export async function deleteCloud(){}export async function idToken(){return '';}`;const scope='score.plays.v1.user.one',records=Array.from({length:120},(_,i)=>({id:'p'+i,game:{name:'카탄',bggId:'13'},date:'2026-10-01',createdAt:'2026-10-01T00:00:00.000Z',rule:'highest',players:[{id:'a',name:'나',color:'#52c7ef',score:i}]})),store=new Map([[scope,JSON.stringify({records,pending:records.map(p=>p.id)})],['score.lastUser.v1','one']]);let writes=0;const set=store.set.bind(store);store.set=(k,v)=>{if(k===scope)writes++;return set(k,v);};const a=await app(store,true,source);Object.assign(a.vm,{active:0,peak:0,saved:[]});await a.changeAuth({uid:'one'});writes=0;await a.get('cloudSync').onclick();assert.equal(new Set(a.vm.saved).size,120);assert.deepEqual(JSON.parse(store.get(scope)).pending,[]);assert.ok(a.vm.peak>1&&a.vm.peak<=25,'uploads run in bounded parallel chunks');assert.ok(writes<=10,`device copy rewritten ${writes} times`);});
test('manual cloud sync downloads everything once, then nothing when unchanged and only changes afterwards',async()=>{const source=`export const cloudConfigured=()=>true;export async function connectCloud(cb){globalThis.changeAuth=cb;}export async function login(){}export async function logout(){}export async function cloudManifest(){return globalThis.manifest;}export async function loadCloud(){globalThis.fullReads++;return globalThis.cloud.map(p=>({...p}));}export async function loadCloudChanges(uid,since){globalThis.changeReads.push(since);return globalThis.changes.map(p=>({...p}));}export async function cloudCount(){return globalThis.cloud.length;}export async function markCloudChanged(){}export async function saveCloud(){}export async function deleteCloud(){}export async function idToken(){return '';}`;const play=(id,score)=>({id,game:{name:'카탄',bggId:'13'},date:'2026-10-01',createdAt:'2026-10-01T00:00:00.000Z',rule:'highest',players:[{id:'a',name:'나',color:'#52c7ef',score}]}),scope='score.plays.v1.user.one',store=new Map([['score.lastUser.v1','one']]);const a=await app(store,true,source);Object.assign(a.vm,{manifest:{plays:100,bggCollection:0,bggPlays:0},cloud:[play('p1',1),play('p2',2)],changes:[],fullReads:0,changeReads:[]});await a.changeAuth({uid:'one'});
 await a.get('cloudSync').onclick();assert.equal(a.vm.fullReads,1);assert.equal(JSON.parse(store.get(scope)).records.length,2);
 await a.get('cloudSync').onclick();assert.equal(a.vm.fullReads,1,'unchanged cloud is not downloaded again');assert.deepEqual(a.vm.changeReads,[]);
 a.vm.manifest={plays:200,bggCollection:0,bggPlays:0};a.vm.cloud=[play('p1',1),play('p2',9)];a.vm.changes=[play('p2',9)];
 await a.get('cloudSync').onclick();assert.equal(a.vm.fullReads,1,'only changes are read');assert.deepEqual(a.vm.changeReads,[100]);const saved=JSON.parse(store.get(scope)).records;assert.equal(saved.length,2,'a changed record overwrites the existing one');assert.equal(saved.find(p=>p.id==='p2').players[0].score,9);
 a.vm.manifest={plays:300,bggCollection:0,bggPlays:0};a.vm.cloud=[play('p1',1)];a.vm.changes=[];
 await a.get('cloudSync').onclick();assert.equal(a.vm.fullReads,2,'a deletion on another device triggers one full read');assert.deepEqual(JSON.parse(store.get(scope)).records.map(p=>p.id),['p1']);
});

